const payload = $input.first().json.body || $input.first().json;
const record = payload.registration || payload.record || payload;

if (!record || !record.id || !record.email || !record.full_name) {
  throw new Error('لم يتم العثور على سجل محفوظ صالح من Supabase.');
}

const formattedDate = new Date(record.created_at || new Date().toISOString()).toLocaleString('ar-SA');

const subject = `مرحبًا بك في مدينتكم يا ${record.full_name} — تأكيد تسجيلك الإلكتروني`;
const html = `
<div dir="rtl" style="font-family:'Cairo','Segoe UI',Tahoma,sans-serif;background:#f3f4f6;padding:32px;color:#111827;">
  <div style="max-width:560px;margin:0 auto;background:#ffffff;border-radius:16px;padding:32px;border:1px solid #e5e7eb;">
    <h2 style="color:#28664F;margin-top:0;">مدينتكم — تأكيد التسجيل الإلكتروني</h2>
    <p>مرحبًا <strong>${record.full_name}</strong>،</p>
    <p>نؤكد لك أنه قد تم حفظ بيانات تسجيلك بنجاح في قاعدة بيانات منصة مدينتكم.</p>
    <div style="background:#f9fafb;border-radius:12px;padding:16px;margin:20px 0;">
      <p style="margin:6px 0;"><strong>الاسم الكامل:</strong> ${record.full_name}</p>
      <p style="margin:6px 0;"><strong>البريد الإلكتروني:</strong> ${record.email}</p>
      <p style="margin:6px 0;"><strong>المهارة التقنية:</strong> ${record.technical_skill}</p>
      <p style="margin:6px 0;"><strong>تاريخ التسجيل:</strong> ${formattedDate}</p>
    </div>
    <p style="color:#6b7280;font-size:13px;">حياتك في المدينة، أكثر اتصالاً — فريق مدينتكم</p>
  </div>
</div>`;

return [{
  json: {
    registrationId: record.id,
    fullName: record.full_name,
    email: record.email,
    technicalSkill: record.technical_skill,
    createdAt: record.created_at,
    emailSubject: subject,
    emailHtml: html
  }
}];

